namespace ClassRonin
{
namespace QRCode
{
const std::uint8_t* RleData() noexcept
{
    return kQRCodeRle;
}

std::uint32_t RleSize() noexcept
{
    return static_cast<std::uint32_t>(sizeof(kQRCodeRle));
}

static inline void WritePixel(std::uint8_t* pixel, PixelFormat format,
    std::uint8_t b, std::uint8_t g, std::uint8_t r)
{
    switch (format)
    {
    case PixelFormat::Bgr24:
        pixel[0] = b; pixel[1] = g; pixel[2] = r;
        break;
    case PixelFormat::Rgb24:
        pixel[0] = r; pixel[1] = g; pixel[2] = b;
        break;
    case PixelFormat::Bgra32:
        pixel[0] = b; pixel[1] = g; pixel[2] = r; pixel[3] = 255;
        break;
    case PixelFormat::Rgba32:
        pixel[0] = r; pixel[1] = g; pixel[2] = b; pixel[3] = 255;
        break;
    }
}

bool Decode(std::vector<std::uint8_t>& pixels, PixelFormat format)
{
    switch (format)
    {
    case PixelFormat::Bgr24:
    case PixelFormat::Rgb24:
    case PixelFormat::Bgra32:
    case PixelFormat::Rgba32:
        break;
    default:
        pixels.clear();
        return false;
    }

    std::vector<std::uint8_t> buffer(static_cast<std::size_t>(PixelBytes(format)));
    if (!Decode(buffer.data(), StrideFor(format), format, RowOrder::TopDown))
    {
        pixels.clear();
        return false;
    }
    pixels.swap(buffer);
    return true;
}

bool Decode(std::uint8_t* destination, int destinationStride, PixelFormat format, RowOrder rowOrder)
{
    switch (format)
    {
    case PixelFormat::Bgr24:
    case PixelFormat::Rgb24:
    case PixelFormat::Bgra32:
    case PixelFormat::Rgba32:
        break;
    default:
        return false;
    }
    if (!destination || destinationStride < StrideFor(format)) return false;

    const int bytesPerPixel = BytesPerPixel(format);
    const unsigned char* src = kQRCodeRle;
    const unsigned char* end = src + sizeof(kQRCodeRle);

    for (int y = 0; y < Height; ++y)
    {
        std::uint8_t* row = destination +
            static_cast<std::size_t>(rowOrder == RowOrder::BottomUp ? (Height - 1 - y) : y) * destinationStride;
        int x = 0;
        while (x < Width)
        {
            if (src + 4 > end) return false;
            const int count = *src++;
            const std::uint8_t b = *src++;
            const std::uint8_t g = *src++;
            const std::uint8_t r = *src++;
            if (count <= 0 || count > Width - x) return false;
            for (int i = 0; i < count; ++i)
            {
                WritePixel(row + static_cast<std::size_t>(x + i) * bytesPerPixel, format, b, g, r);
            }
            x += count;
        }
    }
    return src == end;
}

} // namespace QRCode
} // namespace ClassRonin